// TH18 v1.00a st04bs.ecl.txt BossCard3 (B:822-1039), 「陰陽サフォケイション」.
// Source card t0 is preceded by a 120-frame practice buffer; the control enemy at
// (0,0) owns the spell, the real boss at (0,128) keeps the source hitbox/hurtbox.
const TIME_LIMIT: int = 3420;      // 120 opening buffer + 3300 source timeout
const SOURCE_LIMIT: int = 3300;    // B:850 setInterrupt(0,0,3300,"BossDead")
const OPENING_BUFFER: int = 120;

const TH18_YIN_YANG_R: int = 1056;      // source type 44
const TH18_YIN_YANG_L: int = 1072;      // source type 45
const TH18_BIG_YIN_YANG_R: int = 1088;  // source type 46
const TH18_BIG_YIN_YANG_L: int = 1104;  // source type 47

// B:1005-1038 at2 bullet: EX type8 ANGLE_ACCEL a=100 r=0.0021 s=+-0.034907
// (set_ang_vel/set_accel, cleared after 100 updates), EX type256 OFFSCREEN 600.
// EX type2 ANIM a=1 retreat -4*1.5=-6 is kept through sh_dist. Source BOUNCE
// a=4, b=13 (U+L+R) is re-encoded as target walls 1|2|4=7; the target cap is 3
// bounces (source allows 4), recorded as the engine-cap difference.
xformdef CARD3_AT2(av: int) {
    set_ang_vel(av as angle);
    set_accel(0.0021fx);
    offscreen_keep(600);
    @100 bounce_arm(7, 3);
    set_ang_vel(0bam);
    set_accel(0fx);
}

// B:1005-1038 boss async at2: seven same-frame waves, colors 1..7. Source
// etCount(id,$I0,1) is read at entry; %RANDRAD is sampled at entry, before
// the source wait60. Layer count is 1, so etAngle's 10-degree delta is unused.
sub fire_at2(shape: int, av: int, ways: int, moving: int) {
    var base: angle = (rand(65536) as angle);
    var step: int = (65536 / 7) / ways;
    if moving != 0 {
        card_wait(60);
        if $frame >= self_int(1) { return; }
    } else {
        wait(60);
    }
    var color: int = 1;
    for w in 0..7 {
        sh_reset(0);
        sh_sprite(0, shape, color);
        sh_aim(0, 0);
        sh_ring(0, 1);
        sh_count(0, ways, 1);
        sh_angle(0, base, 0deg);
        sh_speed(0, 1.5fx, 0fx);
        sh_dist(0, -6fx);
        sh_xform(0, CARD3_AT2(av));
        sh_fire(0);
        base = base + (step as angle);
        color = color + 1;
    }
}

// B:895-1003 boss async at: four et streams at absolute top-of-screen offsets
// (%A=0). %B advances 237.32504 and wraps at 192. Speed and inter-shot wait
// follow the four source rank branches; the random angle is %RANDF2*5deg.
async sub top_rain() {
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1fx;
    var gap: int = 44;
    if rank == 1 { gap = 30; }
    if rank == 2 { speed = 1.5fx; gap = 24; }
    if rank == 3 { speed = 2fx; gap = 17; }
    var back: fx = 0fx - 4fx * speed; // B:904-978 ANIM a=1 retreat

    sh_reset(0);
    sh_sprite(0, TH18_BIG_YIN_YANG_R, 1);
    sh_aim(0, 0); sh_ring(0, 0); sh_count(0, 1, 1);
    sh_speed(0, speed, 0fx); sh_dist(0, back);
    sh_reset(1);
    sh_sprite(1, TH18_BIG_YIN_YANG_L, 3);
    sh_aim(1, 0); sh_ring(1, 0); sh_count(1, 1, 1);
    sh_speed(1, speed, 0fx); sh_dist(1, back);
    sh_reset(2);
    sh_sprite(2, TH18_BIG_YIN_YANG_L, 0);
    sh_aim(2, 0); sh_ring(2, 0); sh_count(2, 1, 1);
    sh_speed(2, speed, 0fx); sh_dist(2, back);
    sh_reset(3);
    sh_sprite(3, TH18_BIG_YIN_YANG_L, 1);
    sh_aim(3, 0); sh_ring(3, 0); sh_count(3, 1, 1);
    sh_speed(3, speed, 0fx); sh_dist(3, back);

    var b: fx = 0fx;
    loop {
        for d in 0..4 {
            if $frame >= self_int(1) { return; }
            // B:972-995: %B += 237.32504, wrap if >= 192.
            b = b + 237.32504fx;
            if b >= 192fx { b = b - 384fx; }
            // B:982/993: %RANDF2 * 0.08726646 rad = +-5deg.
            var a: angle = 90deg + (((rand(65536) - 32768) / 36) as angle);
            sh_offset_abs(d, b, 0fx); // B:981 etOffsetAbs($D,%B,%A), %A=0
            sh_angle(d, a, 0deg);
            sh_fire(d);
            wait(gap); // B:984-993 rank wait
        }
    }
}

// B:412 moveRand(120,4,0.5) with B:859 moveLimit(0,128,200,64):
// final bounds x[-100,100], y[96,160]; source inner direction box
// x[-50,50], y[112,144]. Speed slot is linear 0.5 -> 0 over 120 steps.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 120 { speed = (120 - k) as fx / 240fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -100fx { nx = -100fx; }
    if nx > 100fx { nx = 100fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -50fx {
        a = r / 3;
    } else if $self_x > 50fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { return; }
        card_arm_next_step();
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hurtbox(20fx); // Boss entry B:26 setHurtbox(40,40) / 2
    set_hitbox(24fx);  // Boss entry B:27 setHitbox(48,48) / 2
    wait(OPENING_BUFFER);                 // practice buffer
    set_self_int(1, $frame + SOURCE_LIMIT); // source t0
    // B:858 movePosTime(60,4,0,128); entry is already the upstream center.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(120);                            // source t0 -> t120 first call

    var rank: int = global(GVAR_RANK);
    var i0: int = 1;
    var cap: int = 2;
    if rank == 1 { i0 = 3; cap = 5; }
    if rank == 2 { i0 = 4; cap = 6; }
    if rank == 3 { i0 = 5; cap = 6; }
    var f: int = 364; // B:871 %F0=0.034907rad = +2deg/frame in BAM

    spawn top_rain(); // B:870 @BossCard3_at() async
    fire_at2(44, f, i0, 0); // B:874 first at2(44,%F0), waits 60 then fires
    f = -f; // B:875
    loop {
        if $frame >= self_int(1) { return; }
        card_move_rand(); // B:878 moveRand(120,4,0.5)
        card_wait(130);   // B:879
        if $frame >= self_int(1) { return; }
        var shape: int = 45;
        if f > 0 { shape = 44; }
        fire_at2(shape, f, i0, 1); // B:880
        card_wait(100);            // B:881
        if $frame >= self_int(1) { return; }
        f = -f;                    // B:882

        card_move_rand(); // B:883
        card_wait(130);   // B:884
        if $frame >= self_int(1) { return; }
        shape = 45;
        if f > 0 { shape = 44; }
        fire_at2(shape, f, i0, 1); // B:885
        card_wait(100);            // B:886
        if $frame >= self_int(1) { return; }
        f = -f;                    // B:887
        if i0 < cap { i0 = i0 + 1; } // B:888-889
    }
}

async sub control_main() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // B:850/B:852 source timeout 3300 and spell id 40.
    spell_begin(0, 40, none, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control_main);
    _ = spawn_enemy(0fx, 128fx, 19400, 0, 0, 0, boss_main);
    loop { wait(600); }
}
